329: export function advance(task, host) {
330:   const action = nextAction(task, host);
331:   if (['skip', 'approve', 'reuse', 'execute'].includes(action.action)) {
332:     const step = task.steps[action.stage];
333:     step.status = { skip: 'skipped', approve: 'completed', reuse: 'reused', execute: 'running' }[action.action];
334:     step.reason = action.reason;
335:     if (['execute', 'reuse'].includes(action.action)) step.request_binding = digest(host.requests[action.stage]);
336:     if (action.action === 'execute') {
337:       step.attempts++;
338:       step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'uncertain' : 'none';
339:     }
340:     if (action.action === 'skip') {
341:       const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === action.stage);
342:       step.condition_binding = digest(host.conditions[stage.condition]);
343:     }
344:     if (action.action === 'reuse') step.effect_state = host.requests[action.stage].capabilities.some(c => c !== 'read_files') ? 'known' : 'none';
345:     if (action.evidence_ids) step.evidence_ids = action.evidence_ids;
346:     event(task, action.stage, step.status, action.reason);
347:   }
348:   task.next_actions = [action];
349:   return action;
350: }
