352: export function finishStep(task, stageId, evidenceIds, host, failureReason = null) {
353:   const stage = definition(task, host.registry, host.inventory).stages.find(s => s.id === stageId);
354:   const step = task.steps[stageId];
355:   assert(stage && step?.status === 'running', 'Only a running stage may finish');
356:   assert(step.request_binding === digest(host.requests[stageId]), 'Operation scope changed while running');
357:   const denied = permission(stage.skill, stage, task, host);
358:   assert(!denied, denied);
359:   if (failureReason) { step.status = 'validation_failed'; step.reason = failureReason; step.evidence_ids = [...evidenceIds]; }
360:   else {
361:     const provisional = copy(task); provisional.steps[stageId].evidence_ids = evidenceIds;
362:     assert(stepEvidence(provisional, stage, host, step.attempts), 'Completion requires valid, scoped current-attempt evidence and independent review');
363:     step.evidence_ids = [...evidenceIds]; step.status = 'completed'; step.effect_state = step.effect_state === 'none' ? 'none' : 'known';
364:   }
