368: /** Reopening is an explicit host decision; only descendants are reopened.
369:  * Evidence is retained, so still-valid independent checks can be reused.
370:  */
371: export function reopen(task, stageId, host, { reason, source, safeToRetry = false } = {}) {
372:   assert(reason && source, 'Reopen requires a sourced reason');
373:   const workflow = definition(task, host.registry, host.inventory);
374:   assert(task.steps[stageId], 'Unknown stage');
375:   const affected = new Set([stageId]);
376:   let changed = true;
377:   while (changed) { changed = false; for (const stage of workflow.stages) {
378:     if (!affected.has(stage.id) && stage.prerequisites.some(id => affected.has(id))) { affected.add(stage.id); changed = true; }
379:   } }
380:   for (const id of affected) {
381:     const stage = workflow.stages.find(s => s.id === id);
382:     if (['running', 'interrupted'].includes(task.steps[id].status)
383:         || task.steps[id].effect_state === 'uncertain'
384:         || ((writes(stage, host) || task.steps[id].effect_state === 'known' || host.requests?.[id]?.capabilities?.some(c => c !== 'read_files')) && ['completed', 'reused', 'validation_failed'].includes(task.steps[id].status))) {
385:       assert(safeToRetry && host.reconciled?.has(reconciliationBinding(task, id, host)), 'Unknown side effects must be reconciled before retry');
386:     }
387:   }
388:   for (const id of affected) {
389:     const previous = task.steps[id].request_binding;
390:     task.steps[id].status = 'pending'; task.steps[id].effect_state = 'reconciled';
391:     delete task.steps[id].request_binding;
392:     event(task, id, 'pending', `${reason} (${source})`);
393:     if (previous) task.history.at(-1).previous_request_binding = previous;
394:   }
395: }
