398: export function restoreTask(serialized, registry, inventory) {
399:   const task = JSON.parse(serialized);
400:   assert(task.schema_version === 2 && task.id && task.goal && Array.isArray(task.acceptance) && task.acceptance.length, 'Invalid Task Context');
401:   assert(Boolean(task.workflow_id) !== Boolean(task.skill_id), 'Choose one registered workflow or one existing Skill');
402:   assert(task.acceptance.every(item => typeof item === 'string' && item.length)
403:     && new Set(task.acceptance).size === task.acceptance.length, 'Invalid acceptance IDs');
404:   const shape = createTask({ id: task.id, goal: task.goal, acceptance: task.acceptance, workflow_id: task.workflow_id, skill_id: task.skill_id }, registry, inventory);
405:   assert(Object.keys(task).every(key => Object.hasOwn(shape, key)) && Object.keys(shape).every(key => Object.hasOwn(task, key)), 'Unexpected or missing Task Context fields');
406:   for (const name of ['decisions', 'risks', 'permission_refs', 'evidence', 'changes', 'unresolved', 'history', 'next_actions']) assert(Array.isArray(task[name]), `Invalid ${name}`);
407:   assert(task.scope && Array.isArray(task.scope.files) && Array.isArray(task.scope.modules) && Array.isArray(task.scope.interfaces), 'Invalid scope');
408:   runtimeTasks.add(task);
409:   const workflow = definition(task, registry, inventory);
410:   assert(task.steps && Object.keys(task.steps).length === workflow.stages.length, 'Invalid step set');
411:   for (const stage of workflow.stages) {
412:     const step = task.steps[stage.id];
413:     assert(step && states.has(step.status) && Number.isInteger(step.attempts) && step.attempts >= 0 && Array.isArray(step.evidence_ids), 'Invalid step state');
414:     if (step.status === 'running') step.status = 'interrupted';
415:   }
416:   assert(new Set(task.evidence.map(e => e.id)).size === task.evidence.length, 'Duplicate evidence IDs');
417:   // No grants, trustedEvidence, capabilities, conditions or runtime commands restored.
418:   task.next_actions = [];
419:   recovered.set(task, { checkpoint: digest(task), import_id: randomUUID() });
420:   return task;
421: }
